const item = $input.first();
const data = item.json || {};
const templateHtml = String(data.email_template_html || data.html || "").trim();
const markdownCandidate = String(data.generated_email_markdown || data.message || data.enriched_message || "").trim();
const fallbackBody = markdownCandidate
  ? `<p style="margin:0 0 12px 0;">${markdownCandidate.replace(/\n/g, "<br />")}</p>`
  : `<p style="margin:0;">No body content provided.</p>`;
const htmlBody = templateHtml && templateHtml.includes("{{body_html}}")
  ? templateHtml.replace(/\{\{body_html\}\}/g, fallbackBody)
  : fallbackBody;
return [{ json: { ...data, template_intercept_applied: true, intercepted_email_html: htmlBody, composio_email_payload: { body: htmlBody, is_html: true } } }];

const item = \.first().json;
const raw = String(item.message || '').trim();
const lower = raw.toLowerCase();

const isSlackIntent = /\bslack\b/.test(lower) && /(envi|manda|mandar|post|send|mensaje|message|avisa|notifica)/.test(lower);
const isGmailIntent = /\b(gmail|email|correo|e-mail|enviar mail|send mail|send an email|send email)\b/.test(lower);
const isCalendarIntent = /(calendar|calendario|evento|eventos|meeting|reunion)/.test(lower);

let targetHint = '';
let actionMessage = '';
let emailRecipient = '';
let emailSubject = '';
let emailBody = '';

// Extract quoted text
const quoted = raw.match(/["""'']([^"""'']{3,})["""'']/);
if (quoted) actionMessage = quoted[1].trim();

// Slack target extraction
const targetMatch = raw.match(/(?:a|to)\s+([A-Za-z\u00C0-\u00FF0-9._@\-\s]{2,60}?)(?:\s+(?:que\s+diga|diga|saying\s+that|that)|\s*:|\$)/i);
if (targetMatch) targetHint = targetMatch[1].trim();

if (!actionMessage) {
  const sayMatch = raw.match(/(?:que\s+diga|diga|saying\s+that|saying)\s+(.+)\$/i);
  if (sayMatch) actionMessage = sayMatch[1].trim();
}

if (!actionMessage && isSlackIntent) actionMessage = raw;

// Email field extraction (structured text from user)
const recipientMatch = raw.match(/(?:recipient|to|para|destinatario)[\s:]*([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
if (recipientMatch) emailRecipient = recipientMatch[1].trim().toLowerCase();

const subjectMatch = raw.match(/(?:subject|asunto|tema)[\s:]*(.{2,200}?)(?:\n|\$|email body|body|mensaje|contenido)/i);
if (subjectMatch) emailSubject = subjectMatch[1].trim();

const bodyMatch = raw.match(/(?:email body|body|mensaje|contenido)[\s:]*(.{2,2000})/i);
if (bodyMatch) emailBody = bodyMatch[1].trim();

// Fallback: if structured fields missing but email intent detected, try to find raw email
if (isGmailIntent && !emailRecipient) {
  const rawEmail = raw.match(/([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
  if (rawEmail) emailRecipient = rawEmail[1].trim().toLowerCase();
}

let intentType = 'general_chat';
if (isSlackIntent) intentType = 'slack_send_action';
else if (isGmailIntent) intentType = 'gmail_send_action';
else if (/(clickup|tarea|task|asignad|assigned)/.test(lower)) intentType = 'clickup_lookup';
else if (isCalendarIntent) intentType = 'calendar_lookup';

return [{ json: { 
  ...item, 
  intent_type: intentType, 
  action_target_hint: targetHint, 
  action_message: actionMessage,
  email_recipient: emailRecipient,
  email_subject: emailSubject,
  email_body: emailBody
} }];
